Object.assign(SNIP,{"l21decl": "int a[5];                       // 5 ô, chưa khởi tạo: chứa giá trị rác\nint b[5] = {3, 1, 4, 1, 5};     // đủ 5 giá trị\nint c[5] = {7, 8};              // 7 8 0 0 0  (phần còn lại = 0)\nint d[5] = {};                  // 0 0 0 0 0\nint e[] = {2, 4, 6};            // tự đếm: 3 phần tử\nconst int N = 100;\nint f[N];                       // kích thước là hằng: được", "l21func": "// mảng truyền vào hàm KHÔNG bị chép: hàm làm việc trên chính mảng gốc\n// vì vậy phải truyền kèm số phần tử n\nint tong(int a[], int n) {\n    int s = 0;\n    for (int i = 0; i < n; i++) s += a[i];\n    return s;\n}", "l21loop": "#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[100];                         // đủ chỗ cho tối đa 100 số\n    for (int i = 0; i < n; i++) {       // chỉ số chạy 0, 1, ..., n - 1\n        cin >> a[i];\n    }\n    for (int i = n - 1; i >= 0; i--) {  // in ngược\n        cout << a[i] << \" \";\n    }\n    return 0;\n}"});PRESET_NOTES["l21"]={"Ví dụ: Khai báo và in mảng": "Mảng 5 ô có chỉ số 0..4. Dòng a[2] = 9 ghi vào ô thứ ba (tô cam). Vòng lặp đi qua từng ô, mũi tên ▲ chỉ vị trí i.", "Ví dụ: Nhập n phần tử rồi tính tổng": "Mảng khai báo 100 ô nhưng chỉ dùng n ô đầu. Lần lặp thứ nhất ghi từng ô bằng cin; lần lặp thứ hai đọc lại từng ô để cộng dồn vào tong. Hình động chỉ vẽ 40 ô đầu.", "Ví dụ: Tìm số lớn nhất": "Giữ vị trí của số lớn nhất đã thấy (viTri) và so sánh với từng ô mới. Mỗi bước so sánh đọc hai ô (viền xanh): a[i] và a[viTri].", "Ví dụ: Đảo ngược mảng": "Hai chỉ số i (đầu) và j (cuối) tiến lại gần nhau, mỗi lần đổi chỗ hai ô a[i] và a[j]. Chỉ cần n/2 lần đổi chỗ.", "Ví dụ: Mảng truyền vào hàm": "gapDoi nhận chính mảng a của main (không phải bản sao): sửa trong hàm thì a của main đổi theo. Khung Bộ nhớ ghi a ↔ a của main.", "Ví dụ: Đếm tần suất chữ số": "Dùng giá trị làm chỉ số: dem[x]++ tăng ô ứng với chữ số x. Kỹ thuật “mảng đếm” này đếm tần suất chỉ với một lần duyệt.", "Lỗi: chạy tới i <= n (ngoài mảng)": "Lỗi lệch một: i chạy tới 5 nhưng ô cuối là a[4]. Trình mô phỏng dừng ở a[5]; trên máy thật chương trình thường in ra một tổng sai mà không báo gì.", "Bẫy: mảng chưa khởi tạo": "Chỉ a[0] được gán; a[1]..a[4] chứa giá trị rác (ô xám có dấu ?). Tổng in ra là số vô nghĩa. Sửa: int a[5] = {};"};EX_HINTS["l21"]=[["Phải lưu các số vào mảng: muốn đếm số lớn hơn trung bình thì cần duyệt lại sau khi đã biết trung bình.", "Chia số thực: (double)tong / n, in bằng fixed << setprecision(2) (cần #include <iomanip>).", "So sánh a[i] > tb với tb là double."], ["Vòng in chạy từ i = n - 1 xuống tới i = 0 (i >= 0, i--).", "Có thể in dấu cách sau mỗi số; dấu cách thừa ở cuối dòng vẫn được chấp nhận."], ["Dịch n lần thì dãy quay về như cũ, nên chỉ cần dịch k % n lần.", "Không cần dịch thật: phần tử in ở vị trí i của dãy mới là a[(i + k) % n] của dãy cũ.", "Phép % n giữ chỉ số luôn trong khoảng 0..n-1, không bao giờ ra ngoài mảng."]];
