const P21=[{label:"Ví dụ: Khai báo và in mảng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5] = {3, 1, 4, 1, 5};\n    a[2] = 9;\n    for (int i = 0; i < 5; i++) {\n        cout << \"a[\" << i << \"] = \" << a[i] << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]}]},{label:"Ví dụ: Nhập n phần tử rồi tính tổng",input:"5\n4 8 15 16 23",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[100];\n    for (int i = 0; i < n; i++) {\n        cin >> a[i];\n    }\n    int tong = 0;\n    for (int i = 0; i < n; i++) {\n        tong += a[i];\n    }\n    cout << \"Tong = \" << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"],max:12},{type:"vars",names:["n","tong"]}]},{label:"Ví dụ: Tìm số lớn nhất",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[8] = {12, 45, 7, 33, 51, 9, 28, 40};\n    int n = 8;\n    int viTri = 0;\n    for (int i = 1; i < n; i++) {\n        if (a[i] > a[viTri]) {\n            viTri = i;\n        }\n    }\n    cout << \"Lon nhat: a[\" << viTri << \"] = \" << a[viTri] << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i","viTri"]}],predict:[{line:10,v:"viTri",q:"viTri sẽ trỏ tới ô nào sau dòng này?"}]},{label:"Ví dụ: Đảo ngược mảng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[6] = {1, 2, 3, 4, 5, 6};\n    int i = 0, j = 5;\n    while (i < j) {\n        int tam = a[i];\n        a[i] = a[j];\n        a[j] = tam;\n        i++;\n        j--;\n    }\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","j"],range:["i","j"]}]},{label:"Ví dụ: Mảng truyền vào hàm",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid gapDoi(int a[], int n) {\n    for (int i = 0; i < n; i++) {\n        a[i] = a[i] * 2;\n    }\n}\n\nint tong(int a[], int n) {\n    int s = 0;\n    for (int i = 0; i < n; i++) s += a[i];\n    return s;\n}\n\nint main() {\n    int a[4] = {1, 2, 3, 4};\n    gapDoi(a, 4);\n    cout << \"Sau khi gap doi, tong = \" << tong(a, 4) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]}]},{label:"Ví dụ: Đếm tần suất chữ số",input:"8\n3 1 4 1 5 9 2 6",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int dem[10] = {};\n    int n;\n    cin >> n;\n    for (int k = 0; k < n; k++) {\n        int x;\n        cin >> x;\n        dem[x]++;\n    }\n    for (int d = 0; d <= 9; d++) {\n        if (dem[d] > 0) cout << d << \": \" << dem[d] << \" lan\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"dem",label:"dem[0..9]"}]},{label:"Lỗi: chạy tới i <= n (ngoài mảng)",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5] = {2, 4, 6, 8, 10};\n    int tong = 0;\n    for (int i = 0; i <= 5; i++) {\n        tong += a[i];\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]}]},{label:"Bẫy: mảng chưa khởi tạo",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5];\n    a[0] = 10;\n    int tong = 0;\n    for (int i = 0; i < 5; i++) {\n        tong += a[i];\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]}]}];
