makeEx2(document.getElementById("ex-l21"),sim21,[{t:"Trung bình và số lớn hơn trung bình",d:"Nhập n (1 ≤ n ≤ 100) rồi n số nguyên. Dòng 1 in trung bình cộng với 2 chữ số thập phân. Dòng 2 in số lượng phần tử lớn hơn trung bình.",tests:[{in:"5\n1 2 3 4 5",out:"3.00\n2"},{in:"1\n7",out:"7.00\n0"},{in:"4\n10 0 0 0",out:"2.50\n1"},{in:"6\n-3 -1 -2 5 4 3",out:"1.00\n3"},{in:"3\n1 1 2",out:"1.33\n1"}],start:"#include <iostream>\n#include <iomanip>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[100];\n    // nhập mảng, tính tổng, rồi đếm\n    return 0;\n}"},{t:"In ngược dãy số",d:"Nhập n (1 ≤ n ≤ 100) rồi n số nguyên. In các số theo thứ tự ngược lại trên một dòng, cách nhau một dấu cách.",tests:[{in:"5\n1 2 3 4 5",out:"5 4 3 2 1"},{in:"1\n9",out:"9"},{in:"4\n-1 0 7 3",out:"3 7 0 -1"},{in:"3\n100 100 5",out:"5 100 100"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[100];\n    // nhập rồi in ngược\n    return 0;\n}"},{t:"Dịch trái vòng tròn",d:"Nhập n (1 ≤ n ≤ 100), n số nguyên, rồi số k (0 ≤ k ≤ 1000). Dịch dãy sang trái k vị trí theo vòng tròn (phần tử đầu chuyển xuống cuối) rồi in dãy mới.",tests:[{in:"5\n1 2 3 4 5\n2",out:"3 4 5 1 2"},{in:"3\n7 8 9\n0",out:"7 8 9"},{in:"4\n1 2 3 4\n4",out:"1 2 3 4"},{in:"4\n1 2 3 4\n5",out:"2 3 4 1"},{in:"1\n42\n1000",out:"42"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int a[100];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int k;\n    cin >> k;\n    // phần tử ở vị trí mới i là phần tử cũ ở vị trí nào?\n    return 0;\n}"}]);

